import re

with open("attendee.tsx") as f:
    tsx = f.read()

fixed_default_logo = "'data:image/svg+xml;base64,'"

logo_logic_old = """
                    if (config.customLogo) {
                        logoEl.src = config.customLogo;
                        logoEl.classList.remove('hidden');
                    } else {
                        logoEl.classList.add('hidden');
                    }
                    
                    gameNameEl.textContent = game.name || `Rodada ${eventData.activeGameNumber}`;
"""

logo_logic_new = f"""
                    if (config.customLogo) {{
                        logoEl.src = config.customLogo;
                        logoEl.classList.remove('hidden');
                    }} else {{
                        logoEl.src = {fixed_default_logo};
                        logoEl.classList.remove('hidden');
                    }}
                    
                    gameNameEl.textContent = game.name || `Rodada ${{eventData.activeGameNumber}}`;
"""

tsx = tsx.replace(logo_logic_old, logo_logic_new)

with open("attendee.tsx", "w") as f:
    f.write(tsx)
